import asyncio
import base64
import functools
import logging
import json
import os
import pickle
import urllib.request

from .. import config
from ..auth import login
from ..http import request

logging.basicConfig(format='%(levelname)s: %(message)s', level=logging.INFO)

# --- SyngOS Troubadour: calibration results also go to the local agent, which is the room authority when
#     Syng's cloud is unreachable or blocked (see /usr/bin/syng-agent, POST /api/calibration/results).
LOCAL_AGENT = os.environ.get('SYNG_AGENT_URL', 'http://127.0.0.1:8080')
CLOUD_BLOCKED = os.path.exists('/data/syng-cloud-blocked')


def _post_local(path, body):
    try:
        req = urllib.request.Request(LOCAL_AGENT + path, data=json.dumps(body).encode(),
                                     headers={'Content-Type': 'application/json'}, method='POST')
        with urllib.request.urlopen(req, timeout=30) as r:
            out = r.read().decode()
        logging.info(f'[local-agent] {path} -> {out[:200]}')
        return out
    except Exception as e:
        logging.error(f'[local-agent] {path} failed: {e}')
        return None


async def put_calibration_results(results):
    """Returns a coroutine for executing a PUT request against our
       cloud backend to write the results of calibration.
       Troubadour: the local agent gets them first; the cloud is skipped when it is blocked."""
    local = await asyncio.get_running_loop().run_in_executor(None, _post_local, '/api/calibration/results', results)
    if CLOUD_BLOCKED:
        return local

    try:
        token = await login()
    except Exception as e:
        logging.warning(f'cloud login failed ({e}); results kept locally')
        return local

    if 'access_token' not in token:
        return local

    auth_token = token['access_token']

    return await asyncio.get_running_loop().run_in_executor(
        None,
        functools.partial(
            request,
            config.API_GATEWAY_DOMAIN,
            '/v2/cell/calibration',
            'PUT',
            {
                'Authorization': f'Bearer {auth_token}',
                'Content-Type': 'application/json',
            },
            json.dumps(results),
            retries=3
        )
    )

async def put_room_state(room_state):
    """Returns a coroutine for executing a PUT request against our
       cloud backend, to write a new room_state dictionary value.

       room_state : The new room-state value.
       """
    if CLOUD_BLOCKED:
        return None
    token = await login()
    if 'access_token' not in token:
        return None

    auth_token = token['access_token']

    return await asyncio.get_running_loop().run_in_executor(
        None,
        functools.partial(
            request,
            config.API_GATEWAY_DOMAIN,
            '/cell/room_state',
            'PUT',
            {
                'Authorization': f'Bearer {auth_token}',
                'Content-Type': 'application/json',
            },
            json.dumps(room_state),
            retries=3
        )
    )

def post_couch_data(fut_result, fut_token, body):
    try:
        token = fut_token.result()

        # Bail early if auth failed
        if 'access_token' not in token:
            raise RuntimeError("Weird token.")

    except Exception as e:
        fut_result.set_exception(ValueError("Missing valid token"))
        return fut_result

    auth_token = token['access_token']

    def propagate_result(fut):
        e = fut.exception()
        if e is not None:
            fut_result.set_exception(e)
        else:
            fut_result.set_result(fut.result())

    asyncio.get_running_loop().run_in_executor(
        None,
        functools.partial(
            request,
            config.CALIBRATION_COUCH_DOMAIN,
            f'/{config.CALIBRATION_DB_NAME}',
            'POST',
            {
                'Authorization': f'Bearer {auth_token}',
                'Content-Type': 'application/json'
            },
            json.dumps(body),
            retries=3
        )
    ).add_done_callback(propagate_result)

def save_analysis_data(local_file_path: str, body: dict, data: any, save_local_file: bool):
    """Saves analysis data to our remote couchdb instance

       Here we try to auth right before making the request to avoid stale tokens
       and because we don't really mind making the second request."""

    if save_local_file:
        # Store a local copy of the .pickle file for development purposes. NOTE: The /tmp
        # directory is mounted on RAM so just be aware when using.
        #
        with open(local_file_path, 'wb') as f:
            pickle.dump({**body, 'data': data}, f)
        logging.info(f'Wrote local analysis file at {local_file_path}')

    post_body = body

    if data:
        post_body = {**body, **{
            '_attachments': {
                'data.pickle': {
                    'data': base64.b64encode(pickle.dumps(data)).decode('utf-8'),
                    'content_type': 'application/octet-stream'
                }
            }
        }}

    loop = asyncio.get_running_loop()
    fut_result = loop.create_future()

    if CLOUD_BLOCKED:   # Troubadour: no couch upload without the cloud
        fut_result.set_result(None)
        return fut_result
    loop.create_task(login()).add_done_callback(lambda fut_token : post_couch_data(fut_result, fut_token, post_body))
    return fut_result
